/* Generated by build-pwa.mjs. A complete cache is installed before activation. */
const CACHE = "cranea-" + __VERSION__;
const PRECACHE = __PRECACHE__;
const ORIGIN = self.location.origin;

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const queue = [...PRECACHE];
    await Promise.all(Array.from({ length: 6 }, async () => {
      while (queue.length) {
        const url = queue.shift();
        const response = await fetch(new Request(new URL(url, ORIGIN), { cache: "reload" }));
        if (!response.ok || response.redirected) throw new Error(`No se pudo guardar ${url}`);
        await cache.put(url, response);
      }
    }));
    // Updates wait for the player to choose when to restart.
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    await Promise.all((await caches.keys()).filter((key) => key.startsWith("cranea-") && key !== CACHE).map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener("message", (event) => {
  if (event.data?.type === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== "GET" || url.origin !== ORIGIN) return;
  const flight = request.headers.get("RSC") === "1" || url.searchParams.has("_rsc");
  if (flight) {
    // Next falls back to a document navigation when the response isn't Flight.
    // Never cache Flight by URL alone: its router headers change the response.
    event.respondWith(fetch(request).catch(async () => {
      const cache = await caches.open(CACHE);
      return await cache.match(url.pathname) || await cache.match("/offline.html");
    }));
    return;
  }
  if (request.mode === "navigate" || PRECACHE.includes(url.pathname)) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const cached = await cache.match(url.pathname);
      if (cached) return cached;
      try { return await fetch(request); }
      catch { return await cache.match("/offline.html"); }
    })());
  }
});
